fn solve(n: i8) -> bool {
    // Extract the four decimal digits of n:
    // d1 = thousands, d2 = hundreds, d3 = tens, d4 = ones
    let d1 = n / 1000;
    let d2 = (n / 100) % 10;
    let d3 = (n / 10) % 10;
    let d4 = n % 10;

    // Check if either the first three or the last three digits are all equal
    (d1 == d2 && d2 == d3) || (d2 == d3 && d3 == d4)
}

